using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class VenueLightAudit{static VenueLightAudit(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("VenueLightAudit.request"))return;File.Delete("VenueLightAudit.request");var sc=SceneManager.GetActiveScene();var b=new System.Text.StringBuilder();foreach(var f in sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true))){if(!f.sharedMesh||!f.GetComponent<Renderer>())continue;var r=f.GetComponent<Renderer>();var path=AssetDatabase.GetAssetPath(f.sharedMesh);if(!f.name.StartsWith("Circus")&&!path.Contains("CoffeeShopUpgrade")&&!r.sharedMaterials.Any(m=>m&&(m.name.Contains("Cafe")||AssetDatabase.GetAssetPath(m).Contains("Cafe.mat"))))continue;b.AppendLine(f.name+" | active="+f.gameObject.activeInHierarchy+" | "+r.bounds+" | "+path+" | "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name+" "+AssetDatabase.GetAssetPath(m)+" "+m.shader.name:"null")));if(path.Contains("CoffeeShopUpgrade")){var mark=new List<Vector4>();f.sharedMesh.GetUVs(3,mark);b.AppendLine("MARK "+mark.Count+" vertices="+f.sharedMesh.vertexCount+" ys="+f.sharedMesh.vertices.Min(v=>v.y)+","+f.sharedMesh.vertices.Max(v=>v.y)+" examples="+string.Join(";",mark.Distinct().Take(10)));}}File.WriteAllText("FinalEnvironmentRoadReview/VenueLightAudit.txt",b.ToString());}}
